export const taskStatuses=[['all','全部'],['processing','处理中'],['completed','已完成'],['failed','失败'],['cancelled','已取消'],['record','操作记录']];
export function normalizeTasks(records,reports,assets){const findAsset=t=>assets.find(a=>t.id===`${a.type==='report'?'report':'draft'}-${a.id}`||t.url===a.url);const saved=records.map(t=>{const asset=findAsset(t);const status=['completed','failed','cancelled','queued','running'].includes(t.status)?t.status:'record';return {...t,id:String(t.id),title:t.title||asset?.title||'未命名任务',status,category:asset?.type==='report'?'check':'save',typeLabel:asset?.type==='report'?'论文查重':'内容保存',projectId:asset?.projectId||t.projectId||'',stamp:Date.parse(t.createdAt)||0,asset,url:asset?.url||'',origin:'local'};});const reportTasks=reports.filter(r=>!saved.some(t=>t.id==='report-'+r.id)).map(r=>({id:'report-'+r.id,title:r.title||'查重报告',kind:'本地文本比对',category:'check',typeLabel:'论文查重',status:'completed',projectId:r.projectId||'',createdAt:r.createdAt,stamp:Date.parse(r.createdAt)||0,asset:assets.find(a=>a.type==='report'&&a.id===r.id),url:'/precheck/#/report/'+encodeURIComponent(r.id),origin:'local',report:r}));return [...saved,...reportTasks].sort((a,b)=>b.stamp-a.stamp);}
export function statusGroup(t){return ['queued','running'].includes(t.status)?'processing':t.status;}
export function selectTasks(tasks,{status='all',type='all',project='all',query='',days='all'}={},projects=[],now=Date.now()){const names=new Map(projects.map(p=>[p.id,p.name]));const q=query.trim().toLocaleLowerCase(),limit=days==='all'?0:now-Number(days)*86400000;return tasks.filter(t=>(status==='all'||statusGroup(t)===status)&&(type==='all'||t.category===type)&&(project==='all'||(project==='none'?!t.projectId:t.projectId===project))&&(!limit||t.stamp>=limit)&&(!q||[t.title,t.id,t.kind,names.get(t.projectId)||''].join(' ').toLocaleLowerCase().includes(q)));}
